<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requireLogin();$user=Auth::user();$pageTitle='آزمون‌های سازمانی من';
$assignments=Database::fetchAll('SELECT a.*,t.title,t.description,t.time_limit_minutes,r.id result_id,r.final_result,r.risk_level FROM hr_assessment_assignments a JOIN hr_assessment_tests t ON t.id=a.test_id LEFT JOIN hr_assessment_results r ON r.id=(SELECT MAX(r2.id) FROM hr_assessment_results r2 WHERE r2.assignment_id=a.id) WHERE a.employee_id=? ORDER BY FIELD(a.status,"in_progress","assigned","submitted","expired","cancelled"),a.id DESC',[(int)$user['id']]);
require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>آزمون‌های سازمانی</h1><p class="muted">فقط تخصیص‌های مربوط به حساب شما نمایش داده می‌شود.</p></div></div>
<div class="hr-test-grid"><?php foreach($assignments as $a):$expired=$a['due_date']&&$a['due_date']<date('Y-m-d')&&!in_array($a['status'],['submitted','cancelled'],true);$status=$expired?'expired':$a['status'];$labels=['assigned'=>'انجام نشده','in_progress'=>'در حال انجام','submitted'=>'تکمیل شده','expired'=>'منقضی شده','cancelled'=>'لغو شده'];?><article class="card hr-test-card"><header><div><h2><?=e($a['title'])?></h2><span class="badge"><?=e($labels[$status]??$status)?></span></div><small><?=e($a['time_limit_minutes'])?> دقیقه</small></header><p><?=e($a['description'])?></p><p class="muted">مهلت: <?=e($a['due_date']?format_jalali_date($a['due_date']):'بدون محدودیت')?></p><?php if(in_array($status,['assigned','in_progress'],true)):?><a class="btn btn-primary" href="/employee/test_run.php?assignment_id=<?=$a['id']?>"><?=$status==='assigned'?'شروع آزمون':'ادامه آزمون'?></a><?php elseif($status==='submitted'):?><a class="btn" href="/employee/test_run.php?assignment_id=<?=$a['id']?>">مشاهده نتیجه</a><?php endif?></article><?php endforeach?><?php if(!$assignments):?><section class="card"><h2>هنوز آزمونی تخصیص نیافته است</h2><p class="muted">پس از تخصیص توسط منابع انسانی، آزمون در این بخش دیده می‌شود.</p></section><?php endif?></div>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
